def desktop_environment_context(cwd: str) -> str:
    """按真实桌面端的 <environment_context> 结构生成当前环境块。"""
    text = DESKTOP_ENVIRONMENT_CONTEXT_TEMPLATE
    today = datetime.now().strftime("%Y-%m-%d")
    import re
    text = re.sub(r"<current_date>[^<]*</current_date>", f"<current_date>{today}</current_date>", text)
    text = re.sub(r"<cwd>[^<]*</cwd>", lambda m: f"<cwd>{cwd}</cwd>", text, count=1)
    return text
